"""Keep the preview and embedded ESP32 page identical."""
from pathlib import Path

root = Path(__file__).resolve().parent
page = (root / "site/index.html").read_text()
assert ')MOTORHTML"' not in page
(root / "MotorPage.h").write_text(
    '#pragma once\n#include <Arduino.h>\n'
    '// Generated by embed-page.py from site/index.html.\n'
    'const char kMotorPage[] PROGMEM = R"MOTORHTML(' + page + ')MOTORHTML";\n'
)
